const config = $('Load Runtime Config').first().json;
const mode = config.dataSourceMode || 'sheets';
const defaultSla = Number(config.defaultSlaDays ?? 5);
const invoiceMap = new Map();

// --- Reference lookup (vendor SLA) — node does NOT need to be wired ---
const vendorSla = {};
try {
  for (const r of $('Fetch Reference Data').all().map(i => i.json)) {
    if (String(r.record_type || '').toLowerCase() === 'vendor' && r.vendor) {
      vendorSla[String(r.vendor).toLowerCase()] = Number(r.sla_days) || defaultSla;
    }
  }
} catch (e) {}

function normalizeQuickBooks(record) {
  const balance = Number(record.Balance ?? record.TotalAmt ?? 0);
  return {
    invoice_id: String(record.Id ?? '').trim(),
    vendor: record.VendorRef?.name || record.vendor || 'Unknown',
    amount: Number(record.TotalAmt ?? 0),
    received_date: record.TxnDate || '',
    due_date: record.DueDate || '',
    routing_date: (record.MetaData?.CreateTime || '').split('T')[0] || '',
    approved_date: balance <= 0 ? (record.TxnDate || new Date().toISOString().split('T')[0]) : '',
    status: balance > 0 ? 'Pending' : 'Approved',
    approver: record.approver || 'Unassigned',
    department: record.department || 'General',
    exception: String(record.exception ?? 'false'),
    sla_days: record.sla_days != null && record.sla_days !== '' ? Number(record.sla_days) : null
  };
}

function normalizeSheet(record) {
  // Skip reference rows if they ever land in input
  if (record.record_type && !record.invoice_id) return null;

  return {
    invoice_id: String(record.invoice_id ?? '').trim(),
    vendor: record.vendor || 'Unknown',
    amount: Number(record.amount ?? 0),
    received_date: record.received_date || '',
    due_date: record.due_date || '',
    routing_date: record.routing_date || '',
    approved_date: record.approved_date || '',
    status: record.status || 'Pending',
    approver: record.approver || 'Unassigned',
    department: record.department || 'General',
    exception: String(record.exception ?? 'false'),
    sla_days: record.sla_days != null && record.sla_days !== '' ? Number(record.sla_days) : null
  };
}

function applyReferenceSla(inv) {
  if (inv.sla_days == null && inv.vendor) {
    const fromRef = vendorSla[String(inv.vendor).toLowerCase()];
    if (fromRef != null) inv.sla_days = fromRef;
  }
  return inv;
}

function addInvoice(raw, normalizer) {
  const normalized = normalizer(raw);
  if (!normalized?.invoice_id) return;
  invoiceMap.set(normalized.invoice_id, applyReferenceSla(normalized));
}

function isQuickBooksRow(raw) {
  return raw && (raw.Id !== undefined || raw.TotalAmt !== undefined);
}

function isInvoiceRow(raw) {
  return raw && raw.invoice_id && !raw.record_type;
}

// --- Load invoices from correct source ---
if (mode === 'quickbooks') {
  // QuickBooks path: use wired input
  for (const item of $input.all()) {
    const raw = item.json;
    if (!raw || Object.keys(raw).length === 0) continue;
    if (isQuickBooksRow(raw)) addInvoice(raw, normalizeQuickBooks);
  }

  // QB fallback → sheets
  if (invoiceMap.size === 0) {
    try {
      for (const raw of $('Fetch Active Invoices').all().map(i => i.json)) {
        if (isInvoiceRow(raw)) addInvoice(raw, normalizeSheet);
      }
    } catch (e) {}
  }
} else {
  // Sheets path: read invoices explicitly from Fetch Active Invoices
  try {
    for (const raw of $('Fetch Active Invoices').all().map(i => i.json)) {
      if (isInvoiceRow(raw)) addInvoice(raw, normalizeSheet);
    }
  } catch (e) {}

  // Fallback if node name differs or only $input is available
  if (invoiceMap.size === 0) {
    for (const item of $input.all()) {
      const raw = item.json;
      if (!raw || Object.keys(raw).length === 0) continue;
      if (isInvoiceRow(raw)) addInvoice(raw, normalizeSheet);
    }
  }
}

if (invoiceMap.size === 0) {
  return [{
    json: {
      _empty: true,
      referenceVendorsLoaded: Object.keys(vendorSla).length
    }
  }];
}

return Array.from(invoiceMap.values()).map(invoice => ({ json: invoice }));

const config = $('Load Runtime Config').first().json;
const defaultSla = Number(config.defaultSlaDays ?? 5);
const criticalThreshold = Number(config.healthScoreCritical ?? 60);
const warningThreshold = Number(config.healthScoreWarning ?? 80);
const workloadThreshold = Number(config.bottleneckWorkloadThreshold ?? 15);

const invoices = $input.all().map(i => i.json).filter(inv => inv.invoice_id && !inv._empty);

const vendorMaster = {}, vendorRiskTier = {}, approverDirectory = {};
try {
  for (const r of $('Fetch Reference Data').all().map(x => x.json)) {
    const type = String(r.record_type || '').toLowerCase();
    if (type === 'vendor' && r.vendor) {
      vendorMaster[String(r.vendor).toLowerCase()] = Number(r.sla_days || defaultSla);
      if (r.risk_tier) vendorRiskTier[String(r.vendor).toLowerCase()] = r.risk_tier;
    }
    if (type === 'approver' && r.approver) {
      approverDirectory[r.approver] = { email: r.email || '', slack_user_id: r.slack_user_id || '', department: r.department || '' };
    }
  }
} catch (e) {}

function getSlaDays(inv) {
  if (inv.sla_days) return Number(inv.sla_days);
  return vendorMaster[String(inv.vendor || '').toLowerCase()] ?? defaultSla;
}

function daysBetween(a, b) {
  if (!a || !b) return null;
  const s = new Date(a), e = new Date(b);
  if (isNaN(s) || isNaN(e)) return null;
  return Math.round((e - s) / 86400000);
}

const validationWarnings = [], duplicateFlags = [];
const invoiceIds = new Set(), seen = new Map();
for (const inv of invoices) {
  if (invoiceIds.has(inv.invoice_id)) validationWarnings.push(`Duplicate: ${inv.invoice_id}`);
  invoiceIds.add(inv.invoice_id);
  const key = `${String(inv.vendor).toLowerCase()}|${inv.amount}|${inv.received_date}`;
  if (seen.has(key)) duplicateFlags.push({ invoice_id: inv.invoice_id, duplicate_of: seen.get(key) });
  else seen.set(key, inv.invoice_id);
}

let approvedInvoices = 0, pendingInvoices = 0, exceptionCount = 0;
let totalCycleTime = 0, cycleCount = 0, totalApprovalDelay = 0, approvalCount = 0;
const approverStats = {}, departmentStats = {};
const highValueInvoices = [], slaRiskInvoices = [], exceptionInvoices = [];
const vendorRiskExposure = { High: 0, Medium: 0, Low: 0 };
const totalSpend = invoices.reduce((s, inv) => s + Number(inv.amount || 0), 0);
const avgAmount = invoices.length ? totalSpend / invoices.length : 0;
const today = new Date().toISOString().split('T')[0];
let pendingSpend = 0;

for (const inv of invoices) {
  const amount = Number(inv.amount || 0);
  const slaDays = getSlaDays(inv);
  const tier = vendorRiskTier[String(inv.vendor || '').toLowerCase()] || 'Low';
  const cycleTime = daysBetween(inv.received_date, inv.approved_date);
  const approvalDelay = daysBetween(inv.routing_date, inv.approved_date);
  if (inv.status === 'Approved') approvedInvoices++;
  if (inv.status === 'Pending') { pendingInvoices++; pendingSpend += amount; vendorRiskExposure[tier] = (vendorRiskExposure[tier] || 0) + amount; }
  if (String(inv.exception).toLowerCase() === 'true') { exceptionCount++; exceptionInvoices.push({ invoice_id: inv.invoice_id, vendor: inv.vendor, amount }); }
  if (cycleTime !== null) { totalCycleTime += cycleTime; cycleCount++; }
  if (approvalDelay !== null) { totalApprovalDelay += approvalDelay; approvalCount++; }
  if (!approverStats[inv.approver]) approverStats[inv.approver] = { totalAssigned: 0, approvedInvoices: 0, totalDelay: 0, pending: 0 };
  approverStats[inv.approver].totalAssigned++;
  if (inv.status === 'Pending') approverStats[inv.approver].pending++;
  if (approvalDelay !== null) { approverStats[inv.approver].approvedInvoices++; approverStats[inv.approver].totalDelay += approvalDelay; }
  if (!departmentStats[inv.department]) departmentStats[inv.department] = { invoices: 0, totalAmount: 0, pending: 0, totalDelay: 0, delayCount: 0 };
  departmentStats[inv.department].invoices++; departmentStats[inv.department].totalAmount += amount;
  if (inv.status === 'Pending') departmentStats[inv.department].pending++;
  if (approvalDelay !== null) { departmentStats[inv.department].totalDelay += approvalDelay; departmentStats[inv.department].delayCount++; }
  if (amount > avgAmount * 3) highValueInvoices.push({ invoice_id: inv.invoice_id, vendor: inv.vendor, amount });
  if (inv.status === 'Pending') {
    const age = daysBetween(inv.received_date, today);
    if (age !== null && age > slaDays - 1) {
      slaRiskInvoices.push({ invoice_id: inv.invoice_id, vendor: inv.vendor, approver: inv.approver, age_days: age, sla_days: slaDays, days_until_breach: slaDays - age, amount, risk_level: age >= slaDays ? 'Critical' : 'High' });
    }
  }
}

const avgCycleTime = cycleCount ? Number((totalCycleTime / cycleCount).toFixed(2)) : 0;
const avgApprovalDelay = approvalCount ? Number((totalApprovalDelay / approvalCount).toFixed(2)) : 0;
const exceptionRate = invoices.length ? Number(((exceptionCount / invoices.length) * 100).toFixed(2)) : 0;

let topApprover = { approver: 'None', totalAssigned: 0, approvedInvoices: 0, averageDelayDays: 0, workloadScore: 0, pending: 0, slack_user_id: '', email: '' };
let highestWorkload = -1;
const approverAnalytics = [];
for (const [approver, stats] of Object.entries(approverStats)) {
  const avgDelay = stats.approvedInvoices ? stats.totalDelay / stats.approvedInvoices : 0;
  const workloadScore = Number((stats.totalAssigned * (avgDelay || 1) + stats.pending * 2).toFixed(2));
  const record = { approver, totalAssigned: stats.totalAssigned, approvedInvoices: stats.approvedInvoices, pending: stats.pending, averageDelayDays: Number(avgDelay.toFixed(2)), workloadScore, slack_user_id: approverDirectory[approver]?.slack_user_id || '', email: approverDirectory[approver]?.email || '' };
  approverAnalytics.push(record);
  if (workloadScore > highestWorkload) { highestWorkload = workloadScore; topApprover = record; }
}
approverAnalytics.sort((a, b) => b.workloadScore - a.workloadScore);

let topDepartment = { department: 'None', invoices: 0, pending: 0, workloadScore: 0 };
let highestDept = -1;
const departmentAnalytics = Object.entries(departmentStats).map(([department, stats]) => {
  const avgDelay = stats.delayCount ? stats.totalDelay / stats.delayCount : 0;
  const workloadScore = Number((stats.pending * 3 + avgDelay * stats.invoices).toFixed(2));
  const rec = { department, invoices: stats.invoices, pending: stats.pending, spend: stats.totalAmount, workloadScore };
  if (workloadScore > highestDept) { highestDept = workloadScore; topDepartment = rec; }
  return rec;
}).sort((a, b) => b.workloadScore - a.workloadScore);

const slaBreachExposure = slaRiskInvoices.filter(r => r.risk_level === 'Critical').reduce((s, r) => s + Number(r.amount || 0), 0);
const cashAtRisk = { pendingSpend: Number(pendingSpend.toFixed(2)), slaBreachExposure: Number(slaBreachExposure.toFixed(2)), total: Number((pendingSpend + slaBreachExposure).toFixed(2)) };
const escalationCandidates = slaRiskInvoices.sort((a, b) => (a.days_until_breach ?? 0) - (b.days_until_breach ?? 0)).slice(0, 5);

let healthScore = 100;
healthScore -= avgCycleTime * Number(config.cycleTimeWeight ?? 5);
healthScore -= exceptionRate * Number(config.exceptionWeight ?? 1);
healthScore -= pendingInvoices * Number(config.pendingWeight ?? 2);
healthScore -= slaRiskInvoices.filter(r => r.risk_level === 'Critical').length * 3;
healthScore = Math.max(0, Math.min(100, Math.round(healthScore)));

let riskLevel = 'Low';
if (healthScore <= criticalThreshold) riskLevel = 'High';
else if (healthScore <= warningThreshold) riskLevel = 'Medium';

return [{ json: {
  run_date: new Date().toISOString(), dataSource: config.dataSourceMode || 'sheets',
  kpis: { totalInvoices: invoices.length, approvedInvoices, pendingInvoices, totalSpend, avgInvoiceAmount: Number(avgAmount.toFixed(2)), avgCycleTime, avgApprovalDelay, exceptionRate },
  healthScore, riskLevel, bottleneck: topApprover, bottleneckDepartment: topDepartment,
  approverAnalytics, departmentAnalytics, validationWarnings, duplicateFlags,
  highValueInvoices, exceptionInvoices, slaRiskInvoices, vendorRiskExposure, cashAtRisk, escalationCandidates,
  vendorMasterLoaded: Object.keys(vendorMaster).length > 0, approverDirectoryLoaded: Object.keys(approverDirectory).length > 0,
  bottleneckWorkloadThreshold: workloadThreshold
}}];

const config = $('Load Runtime Config').first().json;
const horizon = Number(config.forecastHorizonDays ?? 7);
const criticalThreshold = Number(config.healthScoreCritical ?? 60);
const workloadThreshold = Number(config.bottleneckWorkloadThreshold ?? 15);
const current = $('Calculate KPIs & Bottlenecks').first().json;

const history = $('Fetch Reference Data').all().map(i => i.json)
  .filter(r => String(r.record_type).toLowerCase() === 'kpi_history' && r.date)
  .map(r => ({ date: r.date, avg_cycle_time: Number(r.avg_cycle_time), exception_rate: Number(r.exception_rate), pending_invoices: Number(r.pending_invoices), health_score: Number(r.health_score) }))
  .sort((a, b) => new Date(a.date) - new Date(b.date));

const latest = history[history.length - 1] || { avg_cycle_time: 0, exception_rate: 0, pending_invoices: 0, health_score: 100 };
const prior = history[history.length - 2] || latest;

function pct(cur, prev) { return !prev ? 0 : Number((((cur - prev) / prev) * 100).toFixed(2)); }
function slope(vals) {
  if (vals.length < 2) return 0;
  const n = vals.length; let sx = 0, sy = 0, sxy = 0, sxx = 0;
  for (let i = 0; i < n; i++) { sx += i; sy += vals[i]; sxy += i * vals[i]; sxx += i * i; }
  const d = n * sxx - sx * sx;
  return d === 0 ? 0 : (n * sxy - sx * sy) / d;
}
function zScore(v, samples) {
  if (samples.length < 3) return 0;
  const m = samples.reduce((a, b) => a + b, 0) / samples.length;
  const std = Math.sqrt(samples.reduce((a, b) => a + Math.pow(b - m, 2), 0) / samples.length);
  return std === 0 ? 0 : (v - m) / std;
}

const recent = history.slice(-14);
const pendingSlope = slope(recent.map(r => r.pending_invoices));
const cycleSlope = slope(recent.map(r => r.avg_cycle_time));
const cycleTrendPercent = pct(current.kpis.avgCycleTime, latest.avg_cycle_time);
const exceptionTrendPercent = pct(current.kpis.exceptionRate, latest.exception_rate);
const pendingTrendPercent = pct(current.kpis.pendingInvoices, latest.pending_invoices);
const healthTrendPercent = pct(current.healthScore, latest.health_score);

let overallDirection = 'Stable';
if (cycleTrendPercent > 10 || exceptionTrendPercent > 10 || healthTrendPercent < -10) overallDirection = 'Deteriorating';
else if (cycleTrendPercent < -10 && exceptionTrendPercent < -10 && healthTrendPercent > 10) overallDirection = 'Improving';

const projectedPending7d = Math.max(0, Math.round(current.kpis.pendingInvoices + pendingSlope * horizon));
const projectedCycleTime7d = Number(Math.max(0, current.kpis.avgCycleTime + cycleSlope * horizon).toFixed(2));
const atRiskInvoices = (current.slaRiskInvoices || []).sort((a, b) => (a.days_until_breach ?? 0) - (b.days_until_breach ?? 0)).slice(0, 5);
const slaBreachCount = (current.slaRiskInvoices || []).filter(r => r.risk_level === 'Critical' || (r.days_until_breach ?? 99) <= 0).length;
const slaBreachExposure = atRiskInvoices.reduce((s, r) => s + Number(r.amount || 0), 0);

// Fix: only apply pending surge ratios when pending > 0 (avoids false Critical when pending = 0)
const pendingNow = current.kpis.pendingInvoices;
const pendingSurgeAtRisk = pendingNow > 0 && projectedPending7d > pendingNow * 1.25;
const pendingSurgeCritical = pendingNow > 0 && projectedPending7d > pendingNow * 1.5;

let forecastStatus = 'Stable';
if (slaBreachCount >= 3 || pendingSurgeAtRisk || overallDirection === 'Deteriorating') forecastStatus = 'At Risk';
if (slaBreachCount >= 5 || current.healthScore <= criticalThreshold || pendingSurgeCritical) forecastStatus = 'Critical';

const forecastConfidence = history.length >= 14 ? 'High' : history.length >= 7 ? 'Medium' : 'Low';
const cycleTimeAnomaly = Math.abs(zScore(current.kpis.avgCycleTime, history.map(h => h.avg_cycle_time))) > 2;
const exceptionRateAnomaly = Math.abs(zScore(current.kpis.exceptionRate, history.map(h => h.exception_rate))) > 2;
const pendingVolumeAnomaly = Math.abs(zScore(current.kpis.pendingInvoices, history.map(h => h.pending_invoices))) > 2;
const anomalyFlags = [cycleTimeAnomaly && 'cycle_time', exceptionRateAnomaly && 'exception_rate', pendingVolumeAnomaly && 'pending_volume'].filter(Boolean);
const momentumIndex = Number(((healthTrendPercent * 0.4) - (cycleTrendPercent * 0.2) - (exceptionTrendPercent * 0.2) - (pendingTrendPercent * 0.2)).toFixed(2));

const critical = current.healthScore <= criticalThreshold || forecastStatus === 'Critical';
const bottleneck = (current.bottleneck?.workloadScore ?? 0) >= workloadThreshold;
const slaImminent = slaBreachCount > 0;
const anomaly = anomalyFlags.length > 0;
const stableReport = current.healthScore > criticalThreshold && forecastStatus !== 'Critical';

return [{ json: {
  ...current,
  trends: { previousCycleTime: latest.avg_cycle_time, previousExceptionRate: latest.exception_rate, previousPendingInvoices: latest.pending_invoices, previousHealthScore: latest.health_score, cycleTrendPercent, exceptionTrendPercent, pendingTrendPercent, healthTrendPercent, overallDirection, pendingSlope: Number(pendingSlope.toFixed(3)), cycleSlope: Number(cycleSlope.toFixed(3)), deltaVsPrior: { healthScore: Number((current.healthScore - prior.health_score).toFixed(2)), pendingInvoices: current.kpis.pendingInvoices - Number(prior.pending_invoices), exceptionRate: Number((current.kpis.exceptionRate - prior.exception_rate).toFixed(2)), avgCycleTime: Number((current.kpis.avgCycleTime - prior.avg_cycle_time).toFixed(2)) }, historyDepth: history.length },
  forecast: { forecastStatus, projectedPending7d, projectedCycleTime7d, slaBreachCount, slaBreachExposure: Number(slaBreachExposure.toFixed(2)), atRiskInvoices, horizonDays: horizon, confidence: forecastConfidence },
  anomalies: { cycleTimeAnomaly, exceptionRateAnomaly, pendingVolumeAnomaly, anomalyCount: anomalyFlags.length, anomalyFlags: anomalyFlags.join(', ') || 'none' },
  momentumIndex,
  alertFlags: { critical, bottleneck, slaImminent, anomaly, stableReport, anomalyWarning: anomaly && !critical }
}}];

const data = $('Analyze Trends, Forecast & Anomalies').first().json;
const queue = [];
if (data.alertFlags?.slaImminent && data.escalationCandidates?.length) queue.push({ priority: 'P1', action: 'Fast-track SLA-critical invoices', owner: data.bottleneck?.approver || 'AP Manager', invoiceIds: data.escalationCandidates.map(i => i.invoice_id), dueInDays: 1, trigger: 'sla_critical' });
if (data.alertFlags?.bottleneck) queue.push({ priority: 'P2', action: 'Rebalance approval queue', owner: data.bottleneck?.approver || 'AP Manager', invoiceIds: [], dueInDays: 2, trigger: 'bottleneck' });
if (data.anomalies?.exceptionRateAnomaly) queue.push({ priority: 'P3', action: 'Review exception invoices', owner: 'AP Team', invoiceIds: (data.exceptionInvoices || []).map(i => i.invoice_id), dueInDays: 3, trigger: 'exception_anomaly' });
if (data.trends?.overallDirection === 'Deteriorating' || data.momentumIndex < -5) queue.push({ priority: 'P4', action: 'CFO capacity planning review', owner: 'CFO', invoiceIds: [], dueInDays: 5, trigger: 'forecast_deteriorating' });
return [{ json: { ...data, actionQueue: queue.slice(0, 4) } }];

