let aiData = {};
try {
  let raw = ($json.output || $json.text || JSON.stringify($json)).trim().replace(/```json\n?|```/g, '').trim();
  if (!raw.endsWith('}')) raw += '}';
  aiData = JSON.parse(raw);
} catch (e) {
  aiData = { executiveSummary: 'AI parse failed.', keyRisks: ['Manual review needed'], recommendations: ['Re-run workflow'], positiveFindings: ['KPI engine OK'], priority: 'Medium', overallAssessment: 'Parse error', predictedRiskHorizon: 'Unknown', bottleneckRootCause: 'Unknown', actionQueue: [] };
}
const businessData = $('Build Prioritized Action Queue').first().json;
if (!aiData.actionQueue?.length && businessData.actionQueue?.length) aiData.actionQueue = businessData.actionQueue;
return [{ json: { ...businessData, aiInsights: aiData } }];

const d = $('Parse AI Node').first().json;
const rows = [];

// --- Dashboard row (always 1 item) ---
const approvers = (d.approverAnalytics || []).slice(0, 3);
const dept = d.bottleneckDepartment || {};
const a1 = approvers[0] || {};
const a2 = approvers[1] || {};
const a3 = approvers[2] || {};

rows.push({
  json: {
    sheet_target: 'dashboard',
    run_date: d.run_date,
    health_score: d.healthScore,
    risk_level: d.riskLevel,
    forecast_status: d.forecast?.forecastStatus,
    total_invoices: d.kpis?.totalInvoices,
    pending_invoices: d.kpis?.pendingInvoices,
    exception_rate: d.kpis?.exceptionRate,
    avg_cycle_time: d.kpis?.avgCycleTime,
    bottleneck_approver: d.bottleneck?.approver,
    bottleneck_delay: d.bottleneck?.averageDelayDays,
    ai_priority: d.aiInsights?.priority,
    executive_summary: d.aiInsights?.executiveSummary,
    sla_breach_count: d.forecast?.slaBreachCount,
    anomaly_flags: d.anomalies?.anomalyFlags,
    projected_pending_7d: d.forecast?.projectedPending7d,
    momentum_index: d.momentumIndex ?? 0,
    cash_at_risk: d.cashAtRisk?.total,
    data_source: d.dataSource,
    top_dept: dept.department || '',
    top_dept_pending: dept.pending ?? '',
    top_dept_spend: dept.spend ?? '',
    approver_1: a1.approver || '',
    approver_1_pending: a1.pending ?? '',
    approver_1_delay: a1.averageDelayDays ?? '',
    approver_1_workload: a1.workloadScore ?? '',
    approver_2: a2.approver || '',
    approver_2_pending: a2.pending ?? '',
    approver_2_delay: a2.averageDelayDays ?? '',
    approver_2_workload: a2.workloadScore ?? '',
    approver_3: a3.approver || '',
    approver_3_pending: a3.pending ?? '',
    approver_3_delay: a3.averageDelayDays ?? '',
    approver_3_workload: a3.workloadScore ?? ''
  }
});

// --- SLA queue rows (0–5 items) ---
if (d.alertFlags?.slaImminent || d.alertFlags?.bottleneck) {
  for (const inv of (d.escalationCandidates || [])) {
    rows.push({
      json: {
        sheet_target: 'sla_queue',
        run_date: d.run_date,
        invoice_id: inv.invoice_id,
        vendor: inv.vendor,
        amount: inv.amount,
        approver: inv.approver || d.bottleneck?.approver,
        days_until_breach: inv.days_until_breach,
        inv_risk_level: inv.risk_level,
        status: 'open'
      }
    });
  }
}

return rows;

const data = $('Parse AI Node').first().json;
const config = $('Load Runtime Config').first().json;
const dispatches = [];
if (data.alertFlags?.critical) dispatches.push({ json: { ...data, alert_route: 'critical' } });
if (data.alertFlags?.bottleneck && config.enableClosedLoopActions) dispatches.push({ json: { ...data, alert_route: 'bottleneck' } });
if (data.alertFlags?.stableReport) dispatches.push({ json: { ...data, alert_route: 'stable' } });
if (!dispatches.length) return [{ json: { alert_route: 'none', skip: true } }];
return dispatches;

